function formatTimestamp(dateObj){var year=dateObj.getFullYear();var month=(dateObj.getMonth()+1).toString().padStart(2,'0');var day=dateObj.getDate().toString().padStart(2,'0');var hours=dateObj.getHours().toString().padStart(2,'0');var minutes=dateObj.getMinutes().toString().padStart(2,'0');var seconds=dateObj.getSeconds().toString().padStart(2,'0');return year+'-'+month+'-'+day+' '+hours+':'+minutes+':'+seconds;}function calculateExecutionDuration(startTime,endTime){return(endTime-startTime).toFixed(2)+' ms';}function logEvent(message,level){var lvl=level||'INFO';var time=formatTimestamp(new Date());console.log('['+time+']['+lvl+']'+message);}window.Utils={formatTimestamp:formatTimestamp,calculateExecutionDuration:calculateExecutionDuration,logEvent:logEvent};var galleryItems=[{id:1,title:'Service Worker Cache',category:'Caching',file:'gallery-1.svg',lqip:'gallery-1-lqip.svg',desc:'Caching static assets for instantaneous repeat visits.'},{id:2,title:'Asset Minification',category:'Minification',file:'gallery-2.svg',lqip:'gallery-2-lqip.svg',desc:'Compressing CSS and JavaScript to reduce transfer payload.'},{id:3,title:'Lazy Loading Observer',category:'Lazy Loading',file:'gallery-3.svg',lqip:'gallery-3-lqip.svg',desc:'Loading images on demand as they enter the viewport.'}];function initLazyLoading(){var lazyImages=[].slice.call(document.querySelectorAll('img.progressive-lazy'));if('IntersectionObserver' in window){var imageObserver=new IntersectionObserver(function(entries,observer){entries.forEach(function(entry){if(entry.isIntersecting){var image=entry.target;var fullSrc=image.getAttribute('data-src');if(fullSrc){image.src=fullSrc;image.onload=function(){image.classList.remove('lazy-loading');image.classList.add('lazy-loaded');};}imageObserver.unobserve(image);}});},{rootMargin:'50px 0px'});lazyImages.forEach(function(image){imageObserver.observe(image);});}else{lazyImages.forEach(function(image){image.src=image.getAttribute('data-src');});}}function renderOptimizedGallery(targetId){var container=document.getElementById(targetId);if(!container)return;var html='';galleryItems.forEach(function(item){html+='<article class="card">';html+='<div class="card-image-wrap">';html+='<img class="progressive-lazy lazy-loading" src="images/'+item.lqip+'" data-src="images/'+item.file+'" alt="'+item.title+'" width="800" height="520" loading="lazy" decoding="async"/>';html+='</div>';html+='<div class="card-body">';html+='<span class="card-tag">'+item.category+'</span>';html+='<h3 class="card-title">'+item.title+'</h3>';html+='<p class="card-text">'+item.desc+'</p>';html+='</div>';html+='</article>';});container.innerHTML=html;initLazyLoading();}function registerServiceWorker(){if('serviceWorker' in navigator){navigator.serviceWorker.register('sw.js').catch(function(err){});}}document.addEventListener('DOMContentLoaded',function(){renderOptimizedGallery('gallery-grid');registerServiceWorker();});